\[
\begin{aligned}
(\nabla\cdot\vec{v})
&=\left(\sum_{i=0}^{3}\vec{\delta}_{i}\frac{\partial}{\partial x_i}\cdot\sum_{j=0}^{3}\vec{\delta}_{j}v_j\right)\\
&=\sum_{i=0}^{3}\sum_{j=0}^{3}\left(\vec{\delta}_{i}\frac{\partial}{\partial x_i}\cdot\vec{\delta}_{j}v_j\right)\\
&=\sum_{i=0}^{3}\sum_{j=0}^{3}(\vec{\delta}_{i}\cdot\vec{\delta}_{j})\frac{\partial}{\partial x_i}v_j\\
&=\sum_{i=0}^{3}\sum_{j=0}^{3}\delta_{ij}\frac{\partial v_j}{\partial x_i}\\
&=\frac{\partial v_x}{\partial x}+\frac{\partial v_y}{\partial y}+\frac{\partial v_z}{\partial z}
\end{aligned}
\]
